CREATE TABLE `learning_sessions` (
  `session_id` int NOT NULL AUTO_INCREMENT COMMENT '세션 ID (AUTO_INCREMENT)',
  `user_id` int NOT NULL COMMENT '사용자 ID',
  `chapter_number` int NOT NULL COMMENT '챕터 번호',
  `section_number` int NOT NULL COMMENT '섹션 번호',
  `session_start_time` timestamp NOT NULL COMMENT '세션 시작 시간',
  `session_end_time` timestamp NOT NULL COMMENT '세션 종료 시간',
  `retry_decision_result` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '재학습 결정 결과 (proceed/retry)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '레코드 생성 시간',
  `study_duration_seconds` int DEFAULT NULL COMMENT '해당 세션 학습 소요 시간 (초)',
  PRIMARY KEY (`session_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_chapter_section` (`chapter_number`,`section_number`),
  KEY `idx_user_chapter_section` (`user_id`,`chapter_number`,`section_number`),
  KEY `idx_session_start_time` (`session_start_time`),
  KEY `idx_retry_decision_result` (`retry_decision_result`),
  CONSTRAINT `learning_sessions_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `learning_sessions_chk_1` CHECK ((`chapter_number` > 0)),
  CONSTRAINT `learning_sessions_chk_2` CHECK ((`section_number` > 0)),
  CONSTRAINT `learning_sessions_chk_3` CHECK ((`session_end_time` >= `session_start_time`)),
  CONSTRAINT `learning_sessions_chk_5` CHECK (((`retry_decision_result` in (_utf8mb4'proceed',_utf8mb4'retry')) or (`retry_decision_result` is null)))
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='학습 세션 정보 v2.0';
