DROP TABLE IF EXISTS `session_conversations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `session_conversations` (
  `conversation_id` int NOT NULL AUTO_INCREMENT COMMENT '대화 고유 ID',
  `session_id` int NOT NULL COMMENT '세션 ID (INT 타입)',
  `message_sequence` int NOT NULL COMMENT '메시지 순서',
  `agent_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '에이전트 이름',
  `message_type` enum('user','system','tool') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '메시지 유형',
  `message_content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '메시지 내용',
  `message_timestamp` timestamp NOT NULL COMMENT '메시지 시간',
  `session_progress_stage` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '세션 진행 단계',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '레코드 생성 시간',
  PRIMARY KEY (`conversation_id`),
  UNIQUE KEY `unique_session_message_sequence` (`session_id`,`message_sequence`),
  KEY `idx_session_id` (`session_id`),
  KEY `idx_message_sequence` (`session_id`,`message_sequence`),
  KEY `idx_agent_name` (`agent_name`),
  KEY `idx_message_type` (`message_type`),
  KEY `idx_message_timestamp` (`message_timestamp`),
  KEY `idx_session_progress_stage` (`session_progress_stage`),
  KEY `idx_session_stage_timestamp` (`session_id`,`session_progress_stage`,`message_timestamp`),
  CONSTRAINT `session_conversations_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `learning_sessions` (`session_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=574 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='세션 대화 기록 v2.0';
