--
-- Table structure for table `user_auth_tokens`
--

DROP TABLE IF EXISTS `user_auth_tokens`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_auth_tokens` (
  `token_id` int NOT NULL AUTO_INCREMENT COMMENT '토큰 고유 ID',
  `user_id` int NOT NULL COMMENT '사용자 ID',
  `refresh_token` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JWT 리프레시 토큰',
  `expires_at` timestamp NOT NULL COMMENT '토큰 만료 시간',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '토큰 활성 상태',
  `device_info` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '디바이스 정보',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '토큰 생성 시간',
  PRIMARY KEY (`token_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_refresh_token` (`refresh_token`),
  KEY `idx_expires_at` (`expires_at`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_user_active_expires` (`user_id`,`is_active`,`expires_at`),
  CONSTRAINT `user_auth_tokens_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=184 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='사용자 인증 토큰 v2.0';
/*!40101 SET character_set_client = @saved_cs_client */;

--
