DROP TABLE IF EXISTS `user_statistics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_statistics` (
  `stats_id` int NOT NULL AUTO_INCREMENT COMMENT '통계 고유 ID',
  `user_id` int NOT NULL COMMENT '사용자 ID (각 사용자당 하나의 레코드)',
  `total_study_sessions` int DEFAULT '0' COMMENT '총 학습 세션 수',
  `total_completed_sessions` int DEFAULT '0' COMMENT '완료된 세션 수',
  `total_multiple_choice_count` int DEFAULT '0' COMMENT '총 객관식 문제 수',
  `total_multiple_choice_correct` int DEFAULT '0' COMMENT '객관식 정답 수',
  `multiple_choice_accuracy` decimal(5,2) DEFAULT '0.00' COMMENT '객관식 정답률 (%)',
  `total_subjective_count` int DEFAULT '0' COMMENT '총 주관식 문제 수',
  `total_subjective_score` int DEFAULT '0' COMMENT '주관식 총 점수',
  `subjective_average_score` decimal(5,2) DEFAULT '0.00' COMMENT '주관식 평균 점수',
  `last_study_date` date DEFAULT NULL COMMENT '마지막 학습 날짜',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '레코드 생성 시간',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '마지막 수정 시간',
  `total_study_time_seconds` int DEFAULT NULL COMMENT '총 학습 시간 (초)',
  PRIMARY KEY (`stats_id`),
  UNIQUE KEY `user_id` (`user_id`),
  KEY `idx_total_study_sessions` (`total_study_sessions`),
  KEY `idx_multiple_choice_accuracy` (`multiple_choice_accuracy`),
  KEY `idx_subjective_average_score` (`subjective_average_score`),
  KEY `idx_last_study_date` (`last_study_date`),
  KEY `idx_user_multiple_choice_stats` (`user_id`,`total_multiple_choice_count`,`multiple_choice_accuracy`),
  KEY `idx_user_subjective_stats` (`user_id`,`total_subjective_count`,`subjective_average_score`),
  CONSTRAINT `user_statistics_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `user_statistics_chk_10` CHECK ((`total_subjective_score` >= 0)),
  CONSTRAINT `user_statistics_chk_11` CHECK (((`subjective_average_score` >= 0.00) and (`subjective_average_score` <= 100.00))),
  CONSTRAINT `user_statistics_chk_2` CHECK ((`total_study_sessions` >= 0)),
  CONSTRAINT `user_statistics_chk_3` CHECK ((`total_completed_sessions` >= 0)),
  CONSTRAINT `user_statistics_chk_4` CHECK ((`total_completed_sessions` <= `total_study_sessions`)),
  CONSTRAINT `user_statistics_chk_5` CHECK ((`total_multiple_choice_count` >= 0)),
  CONSTRAINT `user_statistics_chk_6` CHECK ((`total_multiple_choice_correct` >= 0)),
  CONSTRAINT `user_statistics_chk_7` CHECK ((`total_multiple_choice_correct` <= `total_multiple_choice_count`)),
  CONSTRAINT `user_statistics_chk_8` CHECK (((`multiple_choice_accuracy` >= 0.00) and (`multiple_choice_accuracy` <= 100.00))),
  CONSTRAINT `user_statistics_chk_9` CHECK ((`total_subjective_count` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='사용자 학습 통계 v2.0';
